{
  "narrative_summary": "This result rests on the link from Audit Completion to Annual Recurring Revenue. If the audit timeline shifts, more runs could support a different option. Launch in March breaches the constraint that launch cannot happen before the audit closes, and is not available.",
  "story_headlines": {
    "opt_march": "Launch in March fits demand timing but breaches the audit completion constraint stated in the brief.",
    "opt_june": "Launch in June would need the audit timeline and early demand to both hold through that date."
  },
  "robustness_explanation": {
    "summary": "The ordering holds in about 68% of variations, though the result is based on current estimates.",
    "primary_risk": "The link from Audit Completion to Annual Recurring Revenue is the main source of fragility here.",
    "stability_factors": [
      "Early Demand shows a consistent positive relationship with Annual Recurring Revenue across runs."
    ],
    "fragility_factors": [
      "The link from Audit Completion to Annual Recurring Revenue could shift which option more runs support."
    ]
  },
  "readiness_rationale": "The audit closure constraint is not yet reflected as a hard gate on timing, so this comparison needs reframing before either option can be acted on as stated.",
  "evidence_enhancements": {},
  "scenario_contexts": {
    "edge_audit_arr": {
      "trigger_description": "If Audit Completion shifts later relative to the proposed launch timing...",
      "consequence": "...then the most runs would support Launch in June rather than Launch in March."
    }
  },
  "flip_thresholds": [],
  "bias_findings": [],
  "key_assumptions": [
    "The brief's constraint that shipping cannot happen before the audit closes is treated as a hard gate on timing.",
    "The link from Audit Completion to Annual Recurring Revenue assumes the audit's current expected timeline.",
    "The link from Early Demand to Annual Recurring Revenue assumes early demand patterns observed so far continue."
  ],
  "decision_quality_prompts": [
    {
      "question": "What would need to be true about the audit timeline for Launch in June to be the only option that fits the constraint?",
      "principle": "Consider-the-opposite",
      "applies_because": "The named option breaches a stated constraint, so testing what the constraint actually requires is more useful than comparing shares."
    },
    {
      "question": "Who will argue that the audit closure date should shift before committing to a launch date?",
      "principle": "Structured dissent",
      "applies_because": "The comparison currently rests on a timing assumption that has not been reframed against the audit constraint."
    }
  ],
  "framing_check": {
    "addresses_goal": false,
    "concern": "The options compare launch timing by modelled revenue share, but the brief sets a hard constraint, the audit closing, that is not represented as a gate in the comparison.",
    "suggested_reframe": "Frame the decision around dates that are feasible after the audit closes, then compare revenue outcomes only across those feasible dates."
  }
